import SwiftUI
import UIKit

/// Real photos for pictures. Each picture (emoji) maps to an English Wikipedia article
/// (Photos.json, generated by tools/build_vocab.py); the app shows that article's lead
/// photo — freely licensed images from Wikimedia Commons.
///
/// Lookup order: bundled file (HSKPrep/BundledPhotos/<key>.jpg, optional, see
/// tools/download_photos.py) → disk cache → download. Offline with nothing cached,
/// the emoji is shown instead.
final class PhotoStore {
    static let shared = PhotoStore()

    let titles: [String: String] = {
        guard let url = Bundle.main.url(forResource: "Photos", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let map = try? JSONDecoder().decode([String: String].self, from: data) else { return [:] }
        return map
    }()

    private let memory = NSCache<NSString, UIImage>()
    private let cacheDir: URL = {
        let dir = FileManager.default.urls(for: .cachesDirectory, in: .userDomainMask)[0].appendingPathComponent("photos", isDirectory: true)
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        return dir
    }()
    private let session: URLSession = {
        let config = URLSessionConfiguration.default
        config.httpAdditionalHeaders = ["User-Agent": "HSKPrep/1.0 (iOS study app; https://github.com/RamziAbid91/HSKprep)"]
        config.requestCachePolicy = .returnCacheDataElseLoad
        return URLSession(configuration: config)
    }()

    func hasPhoto(_ picture: String) -> Bool { titles[picture] != nil }

    static func fileKey(_ title: String) -> String {
        title.replacingOccurrences(of: " ", with: "_")
            .replacingOccurrences(of: "(", with: "")
            .replacingOccurrences(of: ")", with: "")
    }

    func cachedImage(for picture: String) -> UIImage? {
        guard let title = titles[picture] else { return nil }
        let key = Self.fileKey(title)
        if let img = memory.object(forKey: key as NSString) { return img }
        if let url = Bundle.main.url(forResource: key, withExtension: "jpg", subdirectory: "BundledPhotos"),
           let img = UIImage(contentsOfFile: url.path) {
            memory.setObject(img, forKey: key as NSString); return img
        }
        let file = cacheDir.appendingPathComponent(key + ".jpg")
        if let img = UIImage(contentsOfFile: file.path) {
            memory.setObject(img, forKey: key as NSString); return img
        }
        return nil
    }

    func image(for picture: String) async -> UIImage? {
        if let img = cachedImage(for: picture) { return img }
        guard let title = titles[picture] else { return nil }
        let key = Self.fileKey(title)
        do {
            // 1. Ask Wikipedia for the article's lead image.
            let path = title.replacingOccurrences(of: " ", with: "_")
                .addingPercentEncoding(withAllowedCharacters: .urlPathAllowed) ?? title
            guard let summaryURL = URL(string: "https://en.wikipedia.org/api/rest_v1/page/summary/\(path)") else { return nil }
            let (data, _) = try await session.data(from: summaryURL)
            let summary = try JSONDecoder().decode(Summary.self, from: data)
            guard let src = summary.thumbnail?.source ?? summary.originalimage?.source,
                  let imageURL = URL(string: src) else { return nil }
            // 2. Download and cache it.
            let (imgData, _) = try await session.data(from: imageURL)
            guard let img = UIImage(data: imgData) else { return nil }
            if let jpeg = img.jpegData(compressionQuality: 0.85) {
                try? jpeg.write(to: cacheDir.appendingPathComponent(key + ".jpg"))
            }
            memory.setObject(img, forKey: key as NSString)
            return img
        } catch {
            return nil
        }
    }

    /// Downloads photos ahead of time (e.g. for the current level) so they work offline.
    func prefetch(_ pictures: [String]) async {
        let todo = Array(Set(pictures.filter { hasPhoto($0) && cachedImage(for: $0) == nil }))
        await withTaskGroup(of: Void.self) { group in
            var running = 0
            for p in todo {
                if running >= 4 { await group.next(); running -= 1 }
                group.addTask { _ = await self.image(for: p) }
                running += 1
            }
        }
    }

    var cachedCount: Int {
        Set(titles.values).filter { title in
            FileManager.default.fileExists(atPath: cacheDir.appendingPathComponent(Self.fileKey(title) + ".jpg").path)
        }.count
    }

    private struct Summary: Decodable {
        struct Img: Decodable { let source: String }
        let thumbnail: Img?
        let originalimage: Img?
    }
}

/// Shows the real photo for a picture, or the emoji while loading / offline.
/// Sizes follow the learner's "Picture size" setting.
struct PictureView: View {
    enum Layout {
        case square(CGFloat)   // fixed square
        case banner(CGFloat)   // full width, this tall
        case fill              // square that fills the available width (answer grids)
    }
    enum Zoom { case none, tap, longPress }

    let picture: String
    var layout: Layout
    var corner: CGFloat = 16
    var scaled = true
    var zoom: Zoom = .none

    @AppStorage(Settings.pictureScale) private var pictureScale = 1.0
    @State private var image: UIImage?
    @State private var showZoom = false

    /// Compatibility with the original fixed-size call.
    init(picture: String, size: CGFloat = 120, corner: CGFloat = 16, scaled: Bool = true, zoom: Zoom = .none) {
        self.picture = picture; self.layout = .square(size); self.corner = corner; self.scaled = scaled; self.zoom = zoom
    }

    init(picture: String, layout: Layout, corner: CGFloat = 16, zoom: Zoom = .none) {
        self.picture = picture; self.layout = layout; self.corner = corner; self.zoom = zoom
    }

    private var factor: CGFloat { scaled ? pictureScale : 1 }

    var body: some View {
        content
            .clipShape(RoundedRectangle(cornerRadius: corner, style: .continuous))
            .contentShape(RoundedRectangle(cornerRadius: corner, style: .continuous))
            .modifier(ZoomModifier(zoom: zoom, picture: picture, image: image, showZoom: $showZoom))
            .task(id: picture) {
                image = PhotoStore.shared.cachedImage(for: picture)
                if image == nil, PhotoStore.shared.hasPhoto(picture) {
                    image = await PhotoStore.shared.image(for: picture)
                }
            }
            .accessibilityHidden(true)
    }

    @ViewBuilder private var content: some View {
        switch layout {
        case .square(let size):
            photo(fontSize: size * factor * 0.55).frame(width: size * factor, height: size * factor)
        case .banner(let height):
            photo(fontSize: height * factor * 0.5).frame(maxWidth: .infinity).frame(height: height * factor)
        case .fill:
            Color.clear.aspectRatio(1, contentMode: .fit)
                .overlay { GeometryReader { g in photo(fontSize: g.size.width * 0.55).frame(width: g.size.width, height: g.size.height) } }
        }
    }

    @ViewBuilder private func photo(fontSize: CGFloat) -> some View {
        if let image {
            Image(uiImage: image).resizable().scaledToFill()
                .frame(minWidth: 0, maxWidth: .infinity, minHeight: 0, maxHeight: .infinity)
                .clipped()
        } else {
            Text(picture).font(.system(size: fontSize))
                .frame(maxWidth: .infinity, maxHeight: .infinity)
                .background(Color.secondary.opacity(0.06))
        }
    }
}

/// Tap → full-screen photo; long-press → enlarged preview (used where a tap selects an answer).
private struct ZoomModifier: ViewModifier {
    let zoom: PictureView.Zoom
    let picture: String
    let image: UIImage?
    @Binding var showZoom: Bool

    func body(content: Content) -> some View {
        switch zoom {
        case .none:
            content
        case .tap:
            content
                .overlay(alignment: .bottomTrailing) {
                    Image(systemName: "arrow.up.left.and.arrow.down.right")
                        .font(.caption.bold()).padding(6)
                        .background(.ultraThinMaterial, in: Circle()).padding(8)
                }
                .onTapGesture { showZoom = true }
                .fullScreenCover(isPresented: $showZoom) { PhotoZoomView(picture: picture, image: image) }
        case .longPress:
            content.contextMenu {
                Label("Long-press to enlarge", systemImage: "photo")
            } preview: {
                Group {
                    if let image { Image(uiImage: image).resizable().scaledToFit() }
                    else { Text(picture).font(.system(size: 200)) }
                }
                .frame(width: 340, height: 340)
            }
        }
    }
}

/// Full-screen photo with pinch-to-zoom.
struct PhotoZoomView: View {
    let picture: String
    let image: UIImage?
    @Environment(\.dismiss) private var dismiss
    @State private var scale: CGFloat = 1
    @GestureState private var pinch: CGFloat = 1

    var body: some View {
        ZStack(alignment: .topTrailing) {
            Color.black.ignoresSafeArea()
            Group {
                if let image { Image(uiImage: image).resizable().scaledToFit() }
                else { Text(picture).font(.system(size: 220)) }
            }
            .scaleEffect(scale * pinch)
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .gesture(MagnifyGesture().updating($pinch) { v, s, _ in s = v.magnification }
                .onEnded { v in scale = min(4, max(1, scale * v.magnification)) })
            .onTapGesture(count: 2) { withAnimation { scale = scale > 1 ? 1 : 2.5 } }

            Button { dismiss() } label: {
                Image(systemName: "xmark.circle.fill").font(.largeTitle).symbolRenderingMode(.hierarchical)
                    .foregroundStyle(.white)
            }
            .padding()

            if let title = PhotoStore.shared.titles[picture] {
                Text("Photo: Wikipedia — \(title)").font(.caption).foregroundStyle(.white.opacity(0.7))
                    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .bottom).padding()
            }
        }
    }
}

/// Credits screen for the photos.
struct PhotoCreditsView: View {
    @State private var cached = PhotoStore.shared.cachedCount
    @State private var downloading = false
    @AppStorage(Settings.level) private var level = 1

    private var titles: [String] { Array(Set(PhotoStore.shared.titles.values)).sorted() }

    var body: some View {
        List {
            Section {
                Text("Photos are the lead images of English Wikipedia articles, hosted on Wikimedia Commons under free licences (mostly Creative Commons). Tap an article to see the photo's author and licence.")
                    .font(.footnote)
                LabeledContent("Saved for offline use", value: "\(cached) / \(titles.count)")
                Button {
                    downloading = true
                    Task {
                        await PhotoStore.shared.prefetch(Array(PhotoStore.shared.titles.keys))
                        cached = PhotoStore.shared.cachedCount
                        downloading = false
                    }
                } label: {
                    if downloading { ProgressView() } else { Label("Download all photos", systemImage: "arrow.down.circle") }
                }
                .disabled(downloading)
            }
            Section("Sources") {
                ForEach(titles, id: \.self) { title in
                    if let url = URL(string: "https://en.wikipedia.org/wiki/" + (title.replacingOccurrences(of: " ", with: "_")
                        .addingPercentEncoding(withAllowedCharacters: .urlPathAllowed) ?? "")) {
                        Link(title, destination: url)
                    }
                }
            }
        }
        .navigationTitle("Photo credits")
    }
}
